#!/usr/bin/env node
// Generates apps/web/src/config/shellIcons.generated.ts.
//
// Every react-icons pack is ONE module (react-icons/pi/index.mjs is 5.6 MB) and a
// module lives in exactly one chunk. As soon as the app shell imports a single
// `Pi…` icon, the bundler puts the union of all Pi icons used anywhere in the app
// into a chunk that the entry has to load before React mounts. Shell modules
// therefore import their icons from the generated file instead: one GenIcon
// component per icon, no pack module. Lazy routes keep importing react-icons.
//
// The icon set is not listed anywhere: it is whatever apps/web/src imports from
// `shellIcons.generated`. Add an icon = import it from there, then re-run.
//
//   node scripts/generate-shell-icons.mjs           # write the file
//   node scripts/generate-shell-icons.mjs --check   # fail if the file is stale
//
// No dependencies besides react-icons itself.

import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const SRC = path.join(ROOT, 'apps/web/src');
const OUT = path.join(SRC, 'config/shellIcons.generated.ts');
const MODULE = 'shellIcons.generated';

// Prefix -> packs to search, in order. Fa/Io are the only ambiguous prefixes.
const PACKS = {
  Pi: ['pi'],
  Fi: ['fi'],
  Hi: ['hi'],
  Ri: ['ri'],
  Gi: ['gi'],
  Ci: ['ci'],
  Lu: ['lu'],
  Fa: ['fa', 'fa6'],
  Io: ['io5'],
};

// Names whose pack differs from the first candidate (keeps the original glyph).
const PACK_OVERRIDE = { FaFileWord: ['fa6'] };

function walk(dir, out) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.name === 'node_modules') continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (/\.(ts|tsx)$/.test(e.name) && p !== OUT) out.push(p);
  }
  return out;
}

const IMPORT_RE = new RegExp(
  `import\\s*\\{([^}]*)\\}\\s*from\\s*['"][^'"]*${MODULE.replace('.', '\\.')}['"]`,
  'g'
);

const names = new Set();
for (const file of walk(SRC, [])) {
  const text = readFileSync(file, 'utf8');
  for (const m of text.matchAll(IMPORT_RE)) {
    for (const part of m[1].split(',')) {
      const n = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0];
      if (n) names.add(n);
    }
  }
}

const packSource = new Map();
function pack(id) {
  if (!packSource.has(id)) {
    packSource.set(id, readFileSync(path.join(ROOT, 'node_modules/react-icons', id, 'index.mjs'), 'utf8'));
  }
  return packSource.get(id);
}

const blocks = [];
for (const name of [...names].sort()) {
  const candidates = PACK_OVERRIDE[name] ?? PACKS[name.slice(0, 2)];
  if (!candidates) throw new Error(`${name}: no pack mapping for prefix ${name.slice(0, 2)}`);
  const re = new RegExp(`export function ${name} \\(props\\) \\{\\s*return GenIcon\\(([\\s\\S]*?)\\)\\(props\\);\\s*\\}`);
  let data = null;
  for (const id of candidates) {
    const m = pack(id).match(re);
    if (m) {
      data = m[1];
      break;
    }
  }
  if (!data) throw new Error(`${name}: not found in react-icons/${candidates.join(', ')}`);
  blocks.push(`export function ${name}(props: IconBaseProps): JSX.Element {\n  return GenIcon(${data})(props);\n}\n`);
}

const content = `// AUTO-GENERATED by scripts/generate-shell-icons.mjs - do not edit.
// Per-icon GenIcon components so the app shell never imports a whole react-icons pack.
import { GenIcon, type IconBaseProps } from 'react-icons/lib';

import type { JSX } from 'react';

${blocks.join('\n')}`;

if (process.argv.includes('--check')) {
  let current = '';
  try {
    current = readFileSync(OUT, 'utf8');
  } catch {
    // missing file counts as stale
  }
  if (current !== content) {
    console.error('shellIcons.generated.ts is stale. Run: node scripts/generate-shell-icons.mjs');
    process.exit(1);
  }
  console.log(`shellIcons.generated.ts in sync (${names.size} icons)`);
} else {
  writeFileSync(OUT, content);
  console.log(`wrote ${path.relative(ROOT, OUT)} (${names.size} icons)`);
}
